// Build Context v2: deterministic join + readiness engine. The AI Agent gets facts, not raw tabs.
const cfg = $('Set Configuration Parameters').first().json;
const today = (cfg.today_override && String(cfg.today_override).trim()) || new Date().toISOString().slice(0, 10);
const SLA = Number(cfg.approval_sla_days || 15);
const ROAD = Number(cfg.road_factor || 1.3);
const FAR_GAP_KM = Number(cfg.reassign_gap_km || 30);

const rows = (name) => $(name).all().map(i => i.json)
  .filter(r => Object.values(r).some(v => v !== '' && v !== null && v !== undefined));

const sites = rows('Get Sites');
const visits = rows('Get Scheduled Visits');
const utility = rows('Get Utility Approvals');
const techs = rows('Get Technicians');
const pay = rows('Get Payment Milestones');
const parts = rows('Get Parts');
const history = rows('Get Outbound History').filter(h => String(h.mode) === 'live');

const dayDiff = (a, b) => Math.round((new Date(a) - new Date(b)) / 86400000);
const km = (la1, lo1, la2, lo2) => {
  const R = 6371, r = Math.PI / 180;
  const dLa = (la2 - la1) * r, dLo = (lo2 - lo1) * r;
  const a = Math.sin(dLa / 2) ** 2 + Math.cos(la1 * r) * Math.cos(la2 * r) * Math.sin(dLo / 2) ** 2;
  return Math.round(2 * R * Math.asin(Math.sqrt(a)) * ROAD);
};
const skillsOf = (t) => String(t.skills || '').split(',').map(x => x.trim()).filter(Boolean);
const datesOf = (v) => String(v || '').split(',').map(x => x.trim()).filter(Boolean);
const addDays = (d, n) => { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x.toISOString().slice(0, 10); };

const techOut = techs.map(t => ({
  tech_id: t.tech_id, name: t.name, base_city: t.base_city, skills: skillsOf(t),
  shift_hours_left: Number(t.shift_hours_left), max_visits_per_day: Number(t.max_visits_per_day), status: t.status
}));

let totalBlocked = 0, totalOverdue = 0;
const siteOut = [];

for (const s of sites) {
  if (String(s.install_stage).startsWith('Closed')) continue;
  const id = s.site_id;
  const lat = Number(s.lat), lon = Number(s.lon);
  const unavailable = datesOf(s.unavailable_dates);


  // utility
  const u = utility.find(x => x.site_id === id) || {};
  const daysPending = u.status === 'Pending' ? dayDiff(today, u.submitted_date) : null;
  const utilityOut = {
    status: u.status || 'Unknown', application_no: u.application_no || null,
    days_pending: daysPending, sla_days: SLA, sla_breached: daysPending !== null && daysPending > SLA,
    rejection_reason: u.rejection_reason || null, required_action: u.required_action || null,
    officer_name: u.officer_name || null, officer_reachable: !!u.officer_phone
  };

  // payments
  const p = pay.filter(x => x.site_id === id);
  const blocked = p.filter(x => x.status === 'Blocked');
  const overdue = p.filter(x => x.status === 'Overdue');
  const blockedAmt = blocked.reduce((a, x) => a + Number(x.amount_inr), 0);
  const overdueAmt = overdue.reduce((a, x) => a + Number(x.amount_inr), 0);
  totalBlocked += blockedAmt; totalOverdue += overdueAmt;

  // parts
  const sitePartsAll = parts.filter(x => x.site_id === id);
  const sitePartsNeeded = sitePartsAll.filter(x => x.needed_for === s.required_skill);
  const missing = sitePartsNeeded.filter(x => String(x.in_stock) !== 'Y');
  const partsReadyDate = missing.length
    ? (missing.some(x => !x.eta_date) ? 'unknown' : missing.map(x => x.eta_date).sort().pop())
    : today;

  // technician proximity for the skill this site needs
  const qualified = techs.filter(t => skillsOf(t).includes(s.required_skill))
    .map(t => ({ tech_id: t.tech_id, name: t.name, km_to_site: km(Number(t.current_lat), Number(t.current_lon), lat, lon) }))
    .sort((a, b) => a.km_to_site - b.km_to_site);

  // readiness: what stops a technician visit from converting to cash
  const needsApproval = s.required_skill === 'grid_commissioning';
  const blockers = [];
  if (needsApproval && utilityOut.status !== 'Approved') blockers.push('UTILITY_' + String(utilityOut.status).toUpperCase().replace(/ /g, '_'));
  if (missing.length) blockers.push('PART_MISSING (' + missing.map(x => x.part).join(', ') + '; ready ' + partsReadyDate + ')');
  const planningDays = [today, addDays(today, 1), addDays(today, 2)];
  const feasibleDays = planningDays.filter(d =>
    !unavailable.includes(d) && (partsReadyDate === 'unknown' ? false : d >= partsReadyDate));
  const readiness = {
    visit_blockers: blockers,
    unlock_ready_now: blockers.length === 0 && !!(blockedAmt || s.pending_work),
    customer_unavailable_dates: unavailable,
    earliest_feasible_visit_days_in_window: feasibleDays
  };

  // scheduled visits with trip-waste flags
  const visitOut = visits.filter(v => v.site_id === id).map(v => {
    const flags = [];
    if (String(v.requires_utility_approval) === 'Y' && utilityOut.status !== 'Approved') {
      flags.push('UTILITY_NOT_APPROVED (status: ' + utilityOut.status + ')');
    }
    if (unavailable.includes(v.scheduled_date)) flags.push('CUSTOMER_UNAVAILABLE (' + v.scheduled_date + ')');
    const blocking = missing.filter(x => !x.eta_date || x.eta_date > v.scheduled_date);
    if (blocking.length) flags.push('PART_MISSING (' + blocking.map(x => x.part + ' eta ' + (x.eta_date || 'unknown')).join(', ') + ')');
    const at = techs.find(t => t.tech_id === v.tech_id);
    const assignedKm = at ? km(Number(at.current_lat), Number(at.current_lon), lat, lon) : null;
    if (assignedKm !== null && qualified.length && assignedKm - qualified[0].km_to_site >= FAR_GAP_KM && qualified[0].tech_id !== v.tech_id) {
      flags.push('FAR_TECH (' + assignedKm + ' km vs ' + qualified[0].name + ' ' + qualified[0].km_to_site + ' km)');
    }
    return {
      visit_id: v.visit_id, tech_id: v.tech_id, scheduled_date: v.scheduled_date, task: v.task,
      est_hours: Number(v.est_hours), outdoor_work: v.outdoor_work, requires_utility_approval: v.requires_utility_approval,
      assigned_tech_km: assignedKm, trip_waste_flags: flags
    };
  });

  // communication history (live sends only)
  const recent = history.filter(h => h.site_id === id)
    .sort((a, b) => String(b.sent_at).localeCompare(String(a.sent_at))).slice(0, 4)
    .map(h => ({ sent_at: h.sent_at, audience: h.audience, topic: h.topic, status: h.status }));

  siteOut.push({
    site_id: id, customer: s.customer, city: s.city, capacity_kw: Number(s.capacity_kw),
    preferred_language: s.preferred_language || 'English',
    stage: s.install_stage, stage_pct: Number(s.stage_pct), pending_work: s.pending_work,
    required_skill: s.required_skill, utility: utilityOut, readiness,
    parts: sitePartsAll.map(x => ({ part: x.part, needed_for: x.needed_for, in_stock: x.in_stock, eta_date: x.eta_date || null })),
    payments: {
      blocked_inr: blockedAmt, blocked_reason: blocked.map(x => x.blocked_reason).join('; ') || null,
      overdue_inr: overdueAmt, days_overdue: overdue.length ? dayDiff(today, overdue[0].due_date) : null,
      overdue_reason: overdue.map(x => x.blocked_reason).join('; ') || null,
      reminders_sent: overdue.length ? Number(overdue[0].reminders_sent || 0) : 0,
      last_reminder_date: overdue.length ? (overdue[0].last_reminder_date || null) : null
    },
    qualified_techs_by_distance: qualified,
    scheduled_visits: visitOut,
    recent_outbound: recent
  });
}

const ctx = {
  today, company: cfg.company_name || 'VoltEdge Solar',
  thresholds: { utility_sla_days: SLA, reassign_gap_km: FAR_GAP_KM },
  totals: { blocked_inr: totalBlocked, overdue_inr: totalOverdue },
  technicians: techOut, sites: siteOut
};

return [{ json: {
  run_date: today, sites_in_scope: siteOut.length,
  total_blocked_inr: totalBlocked, total_overdue_inr: totalOverdue,
  context_json: JSON.stringify(ctx)
} }];

