// Validate Plan: deterministic guardrails between the AI plan and anything that gets sent or booked.
const o = JSON.parse(JSON.stringify($json.output || $json));
const ctx = JSON.parse($('Build Contextual Data').first().json.context_json);
const cfg = $('Set Configuration Parameters').first().json;
const today = ctx.today;
const COOL = Number(cfg.cooldown_hours || 24);
const PAY_COOL = Number(cfg.payment_cooldown_hours || 72);
const MAX_REMINDERS = Number(cfg.max_auto_reminders || 3);

const siteMap = Object.fromEntries(ctx.sites.map(s => [s.site_id, s]));
const techMap = Object.fromEntries(ctx.technicians.map(t => [t.tech_id, t]));
const addDays = (d, n) => { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x.toISOString().slice(0, 10); };
const horizonEnd = addDays(today, 2);
const rejections = [];
const rejectedSites = new Set();
const rejectedTechs = new Set();

// ---- 1. visit guardrails ----
const load = {};
const okVisits = [];
for (const v of (o.visit_plan || []).slice().sort((a, b) => a.rank - b.rank)) {
  const s = siteMap[v.site_id], t = techMap[v.tech_id];
  const why = [];
  if (!s) why.push('unknown site');
  if (!t) why.push('unknown technician');
  if (v.scheduled_date < today || v.scheduled_date > horizonEnd) why.push('outside 3-day planning window');
  const hrs = Number(v.est_hours || 0);
  if (s) {
    const isComm = /commission|meter sync|grid sync/i.test(v.action || '');
    if (isComm && s.utility.status !== 'Approved') why.push('commissioning without utility approval (' + s.utility.status + ')');
    if (isComm && t && !t.skills.includes('grid_commissioning')) why.push('technician lacks commissioning skill');
    if ((s.readiness.customer_unavailable_dates || []).includes(v.scheduled_date)) why.push('customer unavailable on that date');
    const part = (s.parts || []).find(p => p.needed_for === s.required_skill && p.in_stock !== 'Y' && (!p.eta_date || p.eta_date > v.scheduled_date));
    if (part) why.push('part not available by then: ' + part.part);
  }
  if (t) {
    const k = v.tech_id + '|' + v.scheduled_date;
    const cur = load[k] || { h: 0, n: 0 };
    if (cur.h + hrs > t.shift_hours_left) why.push('exceeds shift hours');
    else if (cur.n + 1 > t.max_visits_per_day) why.push('exceeds max visits per day');
  }
  if (why.length) {
    rejections.push({ type: 'VISIT_REJECTED', site_id: v.site_id || '', detail: [v.tech_id, v.scheduled_date, v.action].join(' | ') + ' -> ' + why.join('; ') });
    rejectedSites.add(v.site_id);
    rejectedTechs.add(v.tech_id);
  } else {
    okVisits.push(v);
    const k = v.tech_id + '|' + v.scheduled_date;
    load[k] = load[k] || { h: 0, n: 0 };
    load[k].h += hrs; load[k].n += 1;
  }
}

// ---- 2. message guardrails ----
const history = $('Read Outbound History').all().map(i => i.json).filter(h => String(h.mode) === 'live');
const hoursSince = (sentAt) => (new Date(today + 'T07:00:00') - new Date(String(sentAt).replace(' ', 'T'))) / 36e5;
const EXEMPT = ['DISPATCH_BRIEF', 'OWNER_DIGEST', 'GUARDRAIL_ALERT'];
const keptMsgs = [];
for (const m of (o.outbound_messages || [])) {
  const s = siteMap[m.site_id];
  let drop = '';
  if (m.audience !== 'OFFICE' && m.audience !== 'TECHNICIAN' && !s) drop = 'unknown site';
  if (!drop && m.audience === 'CUSTOMER' && ['VISIT_CONFIRMATION', 'RESCHEDULE'].includes(m.topic) && rejectedSites.has(m.site_id)) drop = 'its visit was rejected by guardrails';
  if (!drop && m.audience === 'TECHNICIAN' && m.topic === 'DISPATCH_BRIEF' && rejectedTechs.has(m.recipient_id)) drop = 'technician plan changed by guardrails';
  if (!drop && m.topic === 'PAYMENT_REMINDER') {
    if (!s || !(s.payments.overdue_inr > 0)) drop = 'no overdue amount, never dun a customer who is not overdue';
    else if (s.payments.reminders_sent >= MAX_REMINDERS) drop = 'reminder cap reached, needs owner call';
  }
  if (!drop && m.audience === 'UTILITY' && s && !['Pending', 'Rejected'].includes(s.utility.status)) drop = 'utility has nothing pending for this site';
  if (!drop && !EXEMPT.includes(m.topic)) {
    const lim = m.topic === 'PAYMENT_REMINDER' ? PAY_COOL : COOL;
    const hit = history.find(h => h.site_id === m.site_id && h.audience === m.audience && h.topic === m.topic && hoursSince(h.sent_at) < lim);
    if (hit) drop = 'cooldown (' + lim + 'h) since ' + hit.sent_at;
  }
  if (drop) rejections.push({ type: 'MESSAGE_SUPPRESSED', site_id: m.site_id || '', detail: m.audience + ' ' + m.topic + ' -> ' + drop });
  else keptMsgs.push(m);
}

// ---- 3. fail safe: if any visit was rejected, tell the office instead of acting on a half-valid plan ----
const visitRej = rejections.filter(r => r.type === 'VISIT_REJECTED');
if (visitRej.length) {
  keptMsgs.push({
    audience: 'OFFICE', site_id: '', recipient_id: 'office', recipient_name: 'Dispatch desk', topic: 'GUARDRAIL_ALERT',
    language: 'English', priority: 'HIGH',
    message_text: 'Plan check: ' + visitRej.length + ' AI visit(s) were rejected by guardrails. ' +
      visitRej.map(r => r.site_id + ' (' + r.detail.split('-> ')[1] + ')').join(' ; ') +
      '. Affected technician briefs and customer visit notices were held. Please re-dispatch manually.'
  });
}

o.visit_plan = okVisits;
o.outbound_messages = keptMsgs;
o.guardrail_rejections = rejections;
if (rejections.length) o.summary = (o.summary || '') + ' [Guardrails: ' + rejections.length + ' item(s) removed, see GUARDRAIL rows.]';
return [{ json: { output: o } }];

// Split Plan Rows: one validated plan -> flat rows for the Action_Plan tab.
const o = $json.output || $json;
const runDate = $('Build Contextual Data').first().json.run_date;

const base = {
  run_date: runDate, record_type: '', priority_rank: '', site_id: '', customer: '', tech_id: '', tech_name: '',
  scheduled_date: '', time_slot: '', action: '', reason: '', amount_inr: '', blocker_type: '', owner: '',
  expected_unblock_date: '', combine_with: '', notes: ''
};
const out = [];
const add = (r) => out.push({ json: { ...base, ...r } });

add({
  record_type: 'SUMMARY', priority_rank: 0, action: 'Daily recovery summary',
  reason: o.summary || '', amount_inr: o.recoverable_this_week_inr ?? '',
  notes: 'Total blocked INR: ' + (o.total_blocked_inr ?? '')
});

(o.visit_plan || []).forEach(v => add({
  record_type: 'VISIT_PLAN', priority_rank: v.rank, site_id: v.site_id, customer: v.customer,
  tech_id: v.tech_id, tech_name: v.tech_name, scheduled_date: v.scheduled_date, time_slot: v.time_slot,
  action: v.action, reason: v.reason, amount_inr: v.unlocks_payment_inr ?? 0,
  combine_with: (v.combine_with_site_ids || []).join(', '),
  notes: v.change_vs_original
}));

(o.blocked_payments || []).forEach(b => add({
  record_type: 'BLOCKED_PAYMENT', site_id: b.site_id, customer: b.customer, action: b.next_action,
  reason: b.blocker_detail, amount_inr: b.amount_inr, blocker_type: b.blocker_type, owner: b.owner,
  expected_unblock_date: b.expected_unblock_date, notes: b.milestone
}));

(o.deferred_or_cancelled_visits || []).forEach(d => add({
  record_type: 'DEFERRED_VISIT', site_id: d.site_id, action: d.decision, reason: d.reason,
  scheduled_date: d.new_date, notes: d.original_visit_id
}));

(o.office_actions || []).forEach(a => add({
  record_type: 'OFFICE_ACTION', site_id: a.site_id, action: a.action, reason: a.reason, owner: a.owner,
  expected_unblock_date: a.due_date, amount_inr: a.amount_at_stake_inr ?? ''
}));

(o.outbound_messages || []).forEach(m => add({
  record_type: 'MESSAGE_PLANNED', site_id: m.site_id, action: m.topic, owner: m.audience,
  reason: m.message_text, notes: (m.recipient_name || m.recipient_id || '') + ' | ' + (m.language || '')
}));

(o.guardrail_rejections || []).forEach(g => add({
  record_type: 'GUARDRAIL', site_id: g.site_id, action: g.type, reason: g.detail
}));

return out;

// Build Outbound Messages: resolve real phone numbers from sheets, sanitise for WhatsApp templates, apply dry-run.
const cfg = $('Set Configuration Parameters').first().json;
const o = $('Validate AI Generated Plan').first().json.output;
const sites = $('Read Sites from Sheets').all().map(i => i.json);
const techs = $('Read Technicians from Sheets').all().map(i => i.json);
const util = $('Read Utility Approvals from Sheets').all().map(i => i.json);
const runDate = $('Build Contextual Data').first().json.run_date;

const norm = (p) => String(p || '').replace(/[^0-9]/g, '');
const live = String(cfg.send_mode || '').toLowerCase() === 'live';

return (o.outbound_messages || []).map(m => {
  let phone = '', name = m.recipient_name || '';
  if (m.audience === 'CUSTOMER') {
    const s = sites.find(x => x.site_id === m.site_id);
    phone = norm(s && s.customer_phone); name = s ? s.customer : name;
  } else if (m.audience === 'TECHNICIAN') {
    const t = techs.find(x => x.tech_id === m.recipient_id);
    phone = norm(t && t.phone); name = t ? t.name : name;
  } else if (m.audience === 'OFFICE') {
    phone = norm(cfg.office_phone); name = 'Office';
  } else if (m.audience === 'UTILITY') {
    const u = util.find(x => x.site_id === m.site_id);
    phone = norm(u && u.officer_phone); name = (u && u.officer_name) || name;
  }

  // WhatsApp template variables cannot contain newlines/tabs or 4+ spaces and are capped in length
  let text = String(m.message_text || '').replace(/[\r\n\t]+/g, ' | ').replace(/ {2,}/g, ' ').trim().slice(0, 900);

  // privacy: a customer must never see another customer's name
  if (m.audience === 'CUSTOMER') {
    const leak = sites.some(s => s.site_id !== m.site_id && s.customer && text.toLowerCase().includes(String(s.customer).toLowerCase()));
    if (leak) {
      text = '[Customer message withheld, it mentioned another customer. Site ' + m.site_id + '] ' + text;
      phone = norm(cfg.office_phone); name = 'Office';
    }
  }

  const intended = phone;
  if (!live) {
    phone = norm(cfg.test_phone);
  }

  return { json: {
    run_date: runDate, mode: live ? 'live' : 'dry_run', audience: m.audience, site_id: m.site_id || '',
    recipient_name: name, topic: m.topic, to_phone: phone, intended_phone: intended, message_text: text
  } };
});
